class Solution {
    public double myPow(double x, int n) {
        long exponent = n;
        boolean negative = exponent < 0;
        if (negative) {
            exponent = -exponent;
        }
        double result = 1.0;
        for (long count = 0; count < exponent; count++) {
            result *= x;
        }
        return negative ? 1.0 / result : result;
    }
}

