class Solution {
    public double myPow(double x, int n) {
        long exponent = n;
        if (exponent < 0) {
            x = 1.0 / x;
            exponent = -exponent;
        }
        double result = 1.0;
        while (exponent > 0) {
            if ((exponent & 1L) == 1L) {
                result *= x;
            }
            x *= x;
            exponent >>= 1;
        }
        return result;
    }
}
